import{_ as d,o,c as t,a1 as c}from"./chunks/framework.BKrM4vFX.js";const _=JSON.parse('{"title":"sber-mock — Сбербанк Ecom REST v1.1.11.1","description":"sber-mock — Сбербанк Ecom REST v1.1.11.1. © 2026 ООО «Аксиома» ИНН:7842223709 · https://github.com/rucorp/mock-services · все права защищены Документ проекта mock-services (оригинал: rucorp/mock-services). Третий внешний банк-адаптер Stage 2 (issue #81). Реализо","frontmatter":{"sourcePath":"services/sber-mock/README.md"},"headers":[{"level":1,"title":"sber-mock — Сбербанк Ecom REST v1.1.11.1","slug":"sber-mock-Сбербанк-ecom-rest-v11111","link":"#sber-mock-Сбербанк-ecom-rest-v11111","children":[{"level":2,"title":"Быстрый старт","slug":"Быстрый-старт","link":"#Быстрый-старт","children":[]},{"level":2,"title":"Поддерживаемый Ecom-поток","slug":"Поддерживаемый-ecom-поток","link":"#Поддерживаемый-ecom-поток","children":[]},{"level":2,"title":"Callback Ecom","slug":"callback-ecom","link":"#callback-ecom","children":[]},{"level":2,"title":"Ошибки и протокольные оговорки","slug":"Ошибки-и-протокольные-оговорки","link":"#Ошибки-и-протокольные-оговорки","children":[]},{"level":2,"title":"Сценарии, часы и диагностика","slug":"Сценарии-часы-и-диагностика","link":"#Сценарии-часы-и-диагностика","children":[]},{"level":2,"title":"Переменные окружения","slug":"Переменные-окружения","link":"#Переменные-окружения","children":[]},{"level":2,"title":"Протокольные файлы и тесты","slug":"Протокольные-файлы-и-тесты","link":"#Протокольные-файлы-и-тесты","children":[]},{"level":2,"title":"Байтовые квоты состояния (PD-02)","slug":"Байтовые-квоты-состояния-pd-02","link":"#Байтовые-квоты-состояния-pd-02","children":[]}]}],"relativePath":"services/sber-mock/README.md","filePath":"services/sber-mock/README.md"}'),a={name:"services/sber-mock/README.md"};function r(s,e,i,l,n,m){return o(),t("div",null,[...e[0]||(e[0]=[c(`<p>© 2026 ООО «Аксиома» ИНН:7842223709 · <a href="https://github.com/rucorp/mock-services" target="_blank" rel="noreferrer">https://github.com/rucorp/mock-services</a> · все права защищены Документ проекта mock-services (оригинал: rucorp/mock-services).</p><h1 id="sber-mock-Сбербанк-ecom-rest-v11111" tabindex="-1">sber-mock — Сбербанк Ecom REST v1.1.11.1 <a class="header-anchor" href="#sber-mock-Сбербанк-ecom-rest-v11111" aria-label="Permalink to &quot;sber-mock — Сбербанк Ecom REST v1.1.11.1&quot;">​</a></h1><nav class="doc-static-toc" aria-label="Оглавление"><p class="doc-static-toc__title">Оглавление</p><ul><li class="doc-static-toc__item doc-static-toc__item--1"><a class="doc-static-toc__link" href="#sber-mock-Сбербанк-ecom-rest-v11111">sber-mock — Сбербанк Ecom REST v1.1.11.1</a></li><li class="doc-static-toc__item doc-static-toc__item--2"><a class="doc-static-toc__link" href="#Быстрый-старт">Быстрый старт</a></li><li class="doc-static-toc__item doc-static-toc__item--2"><a class="doc-static-toc__link" href="#Поддерживаемый-ecom-поток">Поддерживаемый Ecom-поток</a></li><li class="doc-static-toc__item doc-static-toc__item--2"><a class="doc-static-toc__link" href="#callback-ecom">Callback Ecom</a></li><li class="doc-static-toc__item doc-static-toc__item--2"><a class="doc-static-toc__link" href="#Ошибки-и-протокольные-оговорки">Ошибки и протокольные оговорки</a></li><li class="doc-static-toc__item doc-static-toc__item--2"><a class="doc-static-toc__link" href="#Сценарии-часы-и-диагностика">Сценарии, часы и диагностика</a></li><li class="doc-static-toc__item doc-static-toc__item--2"><a class="doc-static-toc__link" href="#Переменные-окружения">Переменные окружения</a></li><li class="doc-static-toc__item doc-static-toc__item--2"><a class="doc-static-toc__link" href="#Протокольные-файлы-и-тесты">Протокольные файлы и тесты</a></li><li class="doc-static-toc__item doc-static-toc__item--2"><a class="doc-static-toc__link" href="#Байтовые-квоты-состояния-pd-02">Байтовые квоты состояния (PD-02)</a></li></ul></nav><p>Третий внешний банк-адаптер Stage 2 (issue #81). Реализован по официальной документации Сбербанк Ecom REST и callback/тестового контура. Это новый Ecom JSON API, не legacy Secure Payments: <code>POST /ecomm/gw/partner/api/v1/*.do</code>, <code>userName</code>/<code>password</code> в теле каждого вызова, регистрация → <code>formUrl</code> → hosted-форма/ACS → серверная сверка <code>getOrderStatusExtended.do</code>.</p><h2 id="Быстрый-старт" tabindex="-1">Быстрый старт <a class="header-anchor" href="#Быстрый-старт" aria-label="Permalink to &quot;Быстрый старт&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start:sber</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # http://localhost:3105</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># или общий локальный стенд:</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sber-mock</span></span></code></pre></div><p>Node ≥ 18, zero npm dependencies. Синтетические дефолты — <code>SBERMOCKTEST</code> / <code>mockpass123</code>; это не тестовые креды банка. Фактические env значения при запуске скрыты в логах. Банк выдаёт реальные тестовые <code>userName</code>/<code>password</code> подключённому merchant отдельно; не помещайте их в код, тесты, fixtures или общий compose-файл.</p><h2 id="Поддерживаемый-ecom-поток" tabindex="-1">Поддерживаемый Ecom-поток <a class="header-anchor" href="#Поддерживаемый-ecom-поток" aria-label="Permalink to &quot;Поддерживаемый Ecom-поток&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Маршрут</th><th>Назначение</th></tr></thead><tbody><tr><td><code>POST /ecomm/gw/partner/api/v1/register.do</code></td><td>регистрация одностадийного заказа → <code>{orderId, formUrl}</code></td></tr><tr><td><code>POST /ecomm/gw/partner/api/v1/registerPreAuth.do</code></td><td>регистрация заказа с холдом; контролируется <code>MOCK_SBER_TWO_STAGE</code></td></tr><tr><td><code>POST /ecomm/gw/partner/api/v1/deposit.do</code></td><td>списание суммы, не выше авторизованной; частичное подтверждение поддержано</td></tr><tr><td><code>POST /ecomm/gw/partner/api/v1/reverse.do</code></td><td>отмена холда/доступной для reversal оплаты</td></tr><tr><td><code>POST /ecomm/gw/partner/api/v1/refund.do</code></td><td>полный/частичный refund в пределах ещё не возвращённого списания</td></tr><tr><td><code>POST /ecomm/gw/partner/api/v1/decline.do</code></td><td>отмена до первой попытки ввода карточных данных</td></tr><tr><td><code>POST /ecomm/gw/partner/api/v1/getOrderStatusExtended.do</code></td><td>серверная сверка заказа; <code>orderStatus</code> — отдельный от <code>actionCode</code> статус</td></tr><tr><td><code>GET /payment/{orderId}</code></td><td>тестовая hosted-форма с карточными пресетами</td></tr><tr><td><code>POST /payment/{orderId}/pay</code>, <code>POST /payment/{orderId}/3ds</code></td><td>тестовая форма и ACS; ACS-пароль <code>111111</code></td></tr><tr><td><code>GET /health</code>, <code>GET /openapi.json</code></td><td>healthcheck и OpenAPI 3.1</td></tr><tr><td><code>GET /admin</code>, <code>GET /admin/journal</code>, <code>POST /admin/action</code></td><td>консоль заказов, очереди callback и журнала; действия защищены same-origin + CSRF</td></tr><tr><td><code>/mock/time</code>, <code>/mock/scenarios</code>, <code>/mock/state</code>, <code>/mock/reset</code></td><td>виртуальные часы, хаос/сценарии и состояние песочницы</td></tr><tr><td><code>/sandboxes*</code>, <code>/mock/sandboxes</code></td><td>RFC-001 sandbox/control-plane API</td></tr></tbody></table><p><code>paymentOrder.do</code> не реализован: это прямой карточный server-to-server флоу, доступность которого требует merchant-разрешения; выносить его за scope без владельца нельзя. SberPay/SBP Sandbox, СБП и <code>orderBundle</code> также не входят в адаптер.</p><p>REST-тело — JSON UTF-8 (<code>Content-Type: application/json</code>), валюта только RUB <code>643</code>, суммы — целые копейки. Merchant <code>orderNumber</code> уникален в рамках песочницы; повтор не переигрывает исходный запрос. По умолчанию заказ живёт 1200 секунд и имеет не более трёх попыток оплаты. Детальные примеры регистрации, оплаты, deposit/refund и callback находятся в <a href="./../../docs/integration/sber">гайде интегратора</a>.</p><p><code>errorCode=0</code> означает, что обработан конкретный REST-вызов, а не то, что платёж успешен. Источник истины по заказу — числовой <code>orderStatus</code> 0…6; <code>actionCode</code>/<code>actionCodeDescription</code> описывают результат/причину операции и не подменяют состояние заказа. Состояния и переходы — по официальной документации протокола.</p><h2 id="callback-ecom" tabindex="-1">Callback Ecom <a class="header-anchor" href="#callback-ecom" aria-label="Permalink to &quot;Callback Ecom&quot;">​</a></h2><p>Исходящее Ecom callback — HTTP <code>POST</code> JSON без подписи или checksum, с <code>mdOrder</code>, <code>orderNumber</code>, <code>operation</code>, числовым <code>status</code> (<code>1</code>/<code>0</code>) и опциональным <code>additionalParams</code>. Поддержанные операции: <code>created</code>, <code>approved</code>, <code>deposited</code>, <code>reversed</code>, <code>refunded</code>, <code>declinedByTimeout</code>. Только HTTP 200 считается ACK. По умолчанию очередь делает три попытки с интервалом 60 секунд; локальные виртуальные часы ускоряют retry. Для регистрации callback URL задаётся в <code>dynamicCallbackUrl</code>, либо глобально через <code>MOCK_SBER_CALLBACK_URL</code>.</p><p><strong>Подписи/<code>checksum</code> в Ecom callback нет.</strong> Мок не использует и не эмулирует подпись legacy Secure Payments. Неподписанный callback — сигнал к повторной серверной сверке <code>getOrderStatusExtended.do</code>, а не доказательство успешной оплаты. В отсутствии callback URL очередь не создаётся.</p><h2 id="Ошибки-и-протокольные-оговорки" tabindex="-1">Ошибки и протокольные оговорки <a class="header-anchor" href="#Ошибки-и-протокольные-оговорки" aria-label="Permalink to &quot;Ошибки и протокольные оговорки&quot;">​</a></h2><p>Ответы бизнес-ошибок моделируются как HTTP 200 + <code>{errorCode,errorMessage}</code>; <code>field</code>, <code>hint</code> и <code>doc</code> — диагностическое расширение мока. HTTP 400/404/405/413/ 415/500 применяется к транспортным/инфраструктурным ошибкам. Числа 1…6 и частные соответствия (дубликат, авторизация, неизвестный заказ, неверное состояние, сумма/валидация, системная ошибка) — <strong>[VERIFY]/[FORK]</strong>: локальный срез Ecom фиксирует envelope и отдельные описанные ошибки, но не полный merchant-каталог <code>errorCode</code>. Не используйте эти маппинги как обещание production-шлюза; перед точным контрактным тестом их нужно сверить с подключённым Ecom merchant и владельцем проекта.</p><p><code>orderStatus</code> 0…6 документирован в reference для общего семейства Ecom/RBS. Повторяемые test-card action codes 101 и 116 — сценарии официальных тестовых карт. Всё прочее, где публичный Ecom-срез неполон, остаётся явным мок-форком, а не добавляется под видом подтверждённого протокола.</p><h2 id="Сценарии-часы-и-диагностика" tabindex="-1">Сценарии, часы и диагностика <a class="header-anchor" href="#Сценарии-часы-и-диагностика" aria-label="Permalink to &quot;Сценарии, часы и диагностика&quot;">​</a></h2><p><code>X-Mock-Scenario</code>/<code>/mock/scenarios</code> поддерживают <code>fail</code>, <code>hang</code>, <code>latency</code>, <code>http-500</code>, <code>http-504</code>, <code>webhook-drop</code>/<code>no-callback</code> и <code>webhook-duplicate</code>/<code>callback-duplicate</code>. REST chaos с <code>abortStatus</code> происходит до бизнес-операции. Карточные отказы выбираются официальными тестовыми пресетами. <code>POST /mock/time</code> принимает, например, <code>{&quot;advance&quot;:&quot;+20m&quot;}</code> для истечения заказа или <code>{&quot;advance&quot;:&quot;+60s&quot;}</code> для повторной доставки callback.</p><p>Сценарии, их история, журнал и состояние изолируются по <code>X-Mock-Sandbox</code>. Журнал redacts чувствительные поля; PAN не пишется в REST-журнал и не сохраняется в заказе — в заказе остаётся только маска <code>first6**last4</code>. В hosted-режиме SSRF-проверка исходящих callback включается по умолчанию; <code>SSRF_BLOCKED</code> — терминальный отказ без повтора.</p><h2 id="Переменные-окружения" tabindex="-1">Переменные окружения <a class="header-anchor" href="#Переменные-окружения" aria-label="Permalink to &quot;Переменные окружения&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Переменная</th><th>Default</th><th>Назначение</th></tr></thead><tbody><tr><td><code>MOCK_HOST</code> / <code>MOCK_PORT</code></td><td><code>0.0.0.0</code> / <code>3105</code></td><td>адрес и порт HTTP-сервера</td></tr><tr><td><code>MOCK_SBER_USERNAME</code></td><td><code>SBERMOCKTEST</code></td><td>синтетический merchant-логин</td></tr><tr><td><code>MOCK_SBER_PASSWORD</code></td><td><code>mockpass123</code></td><td>синтетический пароль</td></tr><tr><td><code>MOCK_SBER_PUBLIC_BASE_URL</code></td><td><code>http://localhost:\${MOCK_SBER_HOST_PORT:-3105}</code></td><td>внешний base URL, используемый в <code>formUrl</code></td></tr><tr><td><code>MOCK_SBER_CALLBACK_URL</code></td><td>пусто</td><td>callback URL стенда по умолчанию; <code>dynamicCallbackUrl</code> регистрации приоритетнее</td></tr><tr><td><code>MOCK_SBER_CALLBACK_RETRY_MS</code></td><td><code>60000</code> (<code>60s</code>)</td><td>интервал retry; число в миллисекундах либо длительность (<code>60s</code>, <code>1m</code>)</td></tr><tr><td><code>MOCK_SBER_CALLBACK_MAX_ATTEMPTS</code></td><td><code>3</code></td><td>максимум доставок; значение меньше 1 нормализуется в 1</td></tr><tr><td><code>MOCK_SBER_SESSION_TIMEOUT_SECS</code></td><td><code>1200</code></td><td>срок нового заказа в секундах; поддерживает длительность (<code>20m</code>, <code>1h</code>); registration field <code>sessionTimeoutSecs</code> переопределяет его для конкретного заказа</td></tr><tr><td><code>MOCK_SBER_TWO_STAGE</code></td><td><code>true</code></td><td>разрешить <code>registerPreAuth.do</code> в локальном стенде</td></tr><tr><td><code>MOCK_STATE_FILE</code></td><td>пусто</td><td>сохранение доменного состояния/очереди между рестартами</td></tr><tr><td><code>MOCK_SANDBOX_FILE</code></td><td><code>&lt;MOCK_STATE_FILE&gt;.sandboxes.json</code></td><td>база RFC-001 реестра песочниц (обычно следует суффиксу файла состояния)</td></tr><tr><td><code>MOCK_SANDBOX_SWEEP_MS</code></td><td><code>60000</code></td><td>интервал sweep TTL/retention, когда worker включён</td></tr><tr><td><code>MOCK_BLOCK_PRIVATE_WEBHOOKS</code></td><td><code>false</code> (hosted → <code>true</code>)</td><td>запрет исходящих callback в private/reserved адреса; SSRF-отказ терминален</td></tr><tr><td><code>MOCK_VIRTUAL_CLOCK</code></td><td>текущее время</td><td>начальное значение виртуальных часов</td></tr><tr><td><code>MOCK_ADMIN_TOKEN</code> / <code>MOCK_OPERATOR_TOKEN</code></td><td>пусто</td><td>защита управляющих <code>/admin*</code> и <code>/mock/*</code></td></tr><tr><td><code>MOCK_HOSTED</code></td><td><code>false</code></td><td><code>true</code> включает hosted fail-closed для управляющих поверхностей и default SSRF-защиту</td></tr><tr><td><code>MOCK_TENANCY</code></td><td>авто</td><td>sandbox-модель RFC-001 (<code>off</code>, <code>namespaces</code>, <code>owned</code>)</td></tr><tr><td><code>MOCK_SANDBOX_TOKEN</code></td><td>пусто</td><td>owner-token default sandbox в <code>owned</code>-модели; при <code>MOCK_HOSTED=1</code> без него <code>default</code> не обслуживается (MS-12)</td></tr><tr><td><code>MOCK_SANDBOX_TTL_MS</code> / <code>MOCK_SANDBOX_MAX</code></td><td><code>owned: 24h</code> / <code>owned: 100</code></td><td>аренда и число песочниц; shared sandbox-настройки ядра</td></tr><tr><td><code>MOCK_SANDBOX_MAX_DOCUMENTS</code></td><td><code>owned: 5000</code></td><td>квота заказов + callback-документов на sandbox</td></tr><tr><td><code>MOCK_SANDBOX_RETENTION_MS</code></td><td><code>0</code></td><td>retention терминальных callback-записей; заказы не удаляются</td></tr><tr><td><code>MOCK_SANDBOX_HOST_SUFFIX</code></td><td>пусто</td><td>опциональный hostname-формат sandbox URL</td></tr><tr><td><code>MOCK_SANDBOX_CREATE_LIMIT</code></td><td><code>owned: 20</code></td><td>rate-limit создания sandbox на IP</td></tr></tbody></table><h2 id="Протокольные-файлы-и-тесты" tabindex="-1">Протокольные файлы и тесты <a class="header-anchor" href="#Протокольные-файлы-и-тесты" aria-label="Permalink to &quot;Протокольные файлы и тесты&quot;">​</a></h2><ul><li>Манифест drift-проверки: <a href="https://github.com/rucorp/mock-services/blob/main/protocols/sber-ecom.json" target="_blank" rel="noreferrer"><code>protocols/sber-ecom.json</code></a>.</li><li>OpenAPI: <a href="https://github.com/rucorp/mock-services/blob/main/docs/openapi/sber-mock.openapi.json" target="_blank" rel="noreferrer"><code>docs/openapi/sber-mock.openapi.json</code></a>, также <code>GET /openapi.json</code>.</li><li>Selftest (callback/retry/SSRF, RFC-001 и доменные ветки): <code>npm run test:sber</code>.</li><li>Ограничения безопасности общие с проектом: <a href="./../../SECURITY"><code>SECURITY.md</code></a>.</li></ul><h2 id="Байтовые-квоты-состояния-pd-02" tabindex="-1">Байтовые квоты состояния (PD-02) <a class="header-anchor" href="#Байтовые-квоты-состояния-pd-02" aria-label="Permalink to &quot;Байтовые квоты состояния (PD-02)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Env</th><th>Дефолт</th><th>Назначение</th></tr></thead><tbody><tr><td><code>MOCK_SANDBOX_MAX_STATE_BYTES</code></td><td>пусто: <code>8388608</code> (8 МиБ) при <code>maxDocuments &gt; 0</code>, иначе без лимита</td><td>байты JSON одной песочницы; <code>0</code> выключает</td></tr><tr><td><code>MOCK_SANDBOX_GLOBAL_MAX_STATE_BYTES</code></td><td><code>67108864</code> (64 МиБ)</td><td>сумма байт JSON всех песочниц рантайма, включая <code>default</code>; <code>0</code> выключает</td></tr></tbody></table><p>Значения задаются в целых байтах. Пусто сохраняет дефолты. Квота per-sandbox не ограничивает память контейнера; общий бюджет меньше <code>mem_limit: 128m</code>, но не равен RSS. Превышение глобального бюджета на записи или байтовых квот при импорте <code>/mock/state</code> → HTTP 400, <code>errorCode: 400</code>, <code>kind: &#39;bytes&#39;</code>, <code>code: sandbox_state_budget_exceeded</code> / <code>sandbox_state_quota_exceeded</code>, с откатом отклонённого состояния. Правила/история/журнал остаются volatile. Подробности и границы — <a href="./../../packages/core/README#байтовые-квоты-песочниц-pd-02-74">документация ядра</a>.</p>`,28)])])}const p=d(a,[["render",r]]);export{_ as __pageData,p as default};
